package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.springframework.core.env.*;
final class AttachmentScanningAcceptance {
    static final String PROPERTY="scan-acceptance";
    static void enabled(Environment env,boolean enabled,int port){((ConfigurableEnvironment)env).getPropertySources().addFirst(new MapPropertySource(PROPERTY,Map.of("ATTACHMENT_SCANNING_ENABLED",enabled,"CLAMAV_PORT",port,"WORK_ENABLED",false)));}
    static void reset(Environment env){((ConfigurableEnvironment)env).getPropertySources().remove(PROPERTY);}
    static String api(String id){return "/api/openservice/attachments/"+id+"/scan";}
    static Map<String,Object> page(WorkflowSupport h,String id)throws Exception{return TransferAcceptance.result(h.get(api(id),auth("admin")),200);}
    static String upload(WorkflowSupport h,String record,String text)throws Exception{return object(parsed(h.request("POST",h.binaryPath(record,"scan.txt"),text.getBytes(),"text/plain",auth("admin"))).get("result")).get("sys_id").toString();}
    static Map<String,Object> job(Store store,String id)throws Exception{try(var db=store.open()){return db.one("SELECT s.*,a.content FROM os_attachment_scan s JOIN os_attachment a ON a.sys_id=s.attachment_id WHERE s.attachment_id=?",id);}}
    static void request(WorkflowSupport h,String id)throws Exception{assertEquals(200,h.json("POST",api(id),map("review",page(h,id).get("review"),"reason","Check updated definitions"),auth("admin")).statusCode());}
    static void run(WorkflowSupport h)throws Exception{
        String record=h.add("incident").get("sys_id").toString();String legacy=upload(h,record,"legacy");try(var db=h.store.open()){AttachmentScanning.requireRelease(db,legacy);}assertEquals("unscanned",object(page(h,legacy).get("scan")).get("status"));assertFalse(AttachmentScanning.runOne(h.store));assertEquals(400,h.json("POST",api(legacy),map("review",page(h,legacy).get("review"),"reason","Disabled"),auth("admin")).statusCode());
        try(var server=new ClamScannerTest.Server(ClamScannerTest.VERSION+"\0","stream: OK\0")){enabled(h.environment,true,server.port());String clean=upload(h,record,"clean bytes");assertEquals(true,page(h,clean).get("held"));assertEquals("pending",object(page(h,clean).get("scan")).get("status"));for(String path:List.of("/attachment/"+clean,"/api/now/attachment/"+clean+"/file"))assertEquals(423,h.get(path,auth("admin")).statusCode());new Store(h.environment);assertTrue(AttachmentScanning.runOne(h.store));assertEquals(false,page(h,clean).get("held"));assertEquals("clean",object(page(h,clean).get("scan")).get("status"));assertEquals("clean bytes",html(h.get("/attachment/"+clean,auth("admin"))));assertFalse(AttachmentScanning.runOne(h.store));assertFalse(AttachmentScanning.finish(h.store,job(h.store,clean),map("status","clean","engine","stale")));}
        finally{reset(h.environment);}
        try(var server=new ClamScannerTest.Server(ClamScannerTest.VERSION+"\0","stream: Synthetic FOUND\0")){enabled(h.environment,true,server.port());String infected=upload(h,record,"infected fixture");assertTrue(AttachmentScanning.runOne(h.store));assertEquals("infected",object(page(h,infected).get("scan")).get("status"));var hold=AttachmentHoldsAcceptance.result(h,"/api/openservice/attachment-access/"+infected);assertEquals(423,h.json("POST","/api/openservice/attachment-access/"+infected,map("held",false,"review",hold.get("review"),"reason","Cannot override a detection"),auth("admin")).statusCode());
            enabled(h.environment,false,server.port());assertFalse(AttachmentScanning.runOne(h.store));try(var db=h.store.open()){db.update("UPDATE os_attachment SET content=? WHERE sys_id=?","changed".getBytes(),infected);AttachmentScanning.enqueue(db,infected);db.connection.commit();}assertEquals("pending",object(page(h,infected).get("scan")).get("status"));
            var disabledJob=job(h.store,infected);assertFalse(AttachmentScanning.finish(h.store,disabledJob,map("status","clean","engine","in flight")));enabled(h.environment,true,server.port());var captured=job(h.store,infected);assertTrue(AttachmentScanning.finish(h.store,captured,map("status","clean","engine",ClamScannerTest.VERSION)));assertEquals(true,page(h,infected).get("held"));hold=AttachmentHoldsAcceptance.result(h,"/api/openservice/attachment-access/"+infected);assertEquals(200,h.json("POST","/api/openservice/attachment-access/"+infected,map("held",false,"review",hold.get("review"),"reason","Clean current content reviewed"),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_attachment SET content=? WHERE sys_id=?","changed again".getBytes(),infected);var failure=assertThrows(Failure.class,()->AttachmentScanning.requireRelease(db,infected));assertEquals(423,failure.status);db.connection.rollback();}}
        finally{reset(h.environment);}
        int closed;try(var socket=new java.net.ServerSocket(0)){closed=socket.getLocalPort();}try{enabled(h.environment,true,closed);String unavailable=upload(h,record,"scanner down");assertTrue(AttachmentScanning.runOne(h.store));assertEquals("unavailable",object(page(h,unavailable).get("scan")).get("status"));assertEquals(true,page(h,unavailable).get("held"));request(h,unavailable);assertEquals("pending",object(page(h,unavailable).get("scan")).get("status"));var captured=job(h.store,unavailable);request(h,unavailable);assertFalse(AttachmentScanning.finish(h.store,captured,map("status","clean","engine","old")));captured=job(h.store,unavailable);try(var db=h.store.open()){db.update("UPDATE os_attachment SET content=? WHERE sys_id=?","replacement".getBytes(),unavailable);db.connection.commit();}assertFalse(AttachmentScanning.finish(h.store,captured,map("status","clean","engine","old")));captured=job(h.store,unavailable);try(var db=h.store.open()){db.update("UPDATE os_attachment SET hold_revision=hold_revision+1 WHERE sys_id=?",unavailable);db.connection.commit();}assertTrue(AttachmentScanning.finish(h.store,captured,map("status","clean","engine","new")));assertEquals(true,page(h,unavailable).get("held"));String held=upload(h,record,"manual hold during scan");var heldJob=job(h.store,held);try(var db=h.store.open()){db.update("UPDATE os_attachment SET hold_revision=hold_revision+1 WHERE sys_id=?",held);db.connection.commit();}assertTrue(AttachmentScanning.finish(h.store,heldJob,map("status","clean","engine","new")));assertEquals(true,page(h,held).get("held"));request(h,unavailable);captured=job(h.store,unavailable);try(var db=h.store.open()){db.update("DELETE FROM os_attachment WHERE sys_id=?",unavailable);db.connection.commit();}assertFalse(AttachmentScanning.finish(h.store,captured,map("status","clean","engine","deleted")));assertFalse(AttachmentScanning.runOne(h.store));try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_attachment_scan WHERE attachment_id=?",unavailable));}}
        finally{reset(h.environment);}
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        h.account("ScanReader","reader");String record=h.add("incident").get("sys_id").toString(),id=upload(h,record,"legacy held");String api=api(id),ui="/admin/attachments/"+id+"/scan";try{enabled(h.environment,true,1);var view=page(h,id);var body=map("review",view.get("review"),"reason","Reviewed scan");assertEquals(401,h.get(api,null).statusCode());assertEquals(403,h.get(api,auth("ScanReader")).statusCode());assertEquals(403,h.json("POST",api,body,auth("ScanReader")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());assertEquals(405,h.json("PUT",api,body,auth("admin")).statusCode());assertEquals(400,h.get(api+"?bad=x",auth("admin")).statusCode());assertEquals(403,h.form(ui,body,auth("admin")).statusCode());assertEquals(400,h.json("POST",api,map(),auth("admin")).statusCode());assertEquals(400,h.json("POST",api,map("review",view.get("review"),"reason",""),auth("admin")).statusCode());assertEquals(302,h.protectedForm(ui,body,auth("admin")).statusCode());assertEquals(409,h.json("POST",api,body,auth("admin")).statusCode());Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}try{assertEquals(403,h.get(api,auth("admin")).statusCode());assertEquals(403,h.json("POST",api,body,auth("admin")).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}}
            TransferAcceptance.seed();String imported=MigrationSource.key(12),migration=TransferAcceptance.result(h.json("POST",TransferAcceptance.API,TransferAcceptance.plan(),auth("admin")),201).get("job_id").toString();TransferAcceptance.fetch(h,migration);assertEquals(200,h.json("POST",TransferAcceptance.API+"/"+migration+"/preview",map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_attachment_scan WHERE attachment_id=?",imported));}TransferAcceptance.result(h.json("POST",TransferAcceptance.API+"/"+migration+"/apply",map(),auth("admin")),200);assertEquals("pending",object(page(h,imported).get("scan")).get("status"));assertEquals(423,h.get("/attachment/"+imported,auth("admin")).statusCode());
        }finally{reset(h.environment);}
    }
}
